import 'package:flutter/material.dart'; import '../services/theme_service.dart'; import '../services/reciter_service.dart'; import '../services/prayer_times_service.dart'; import '../services/notification_service.dart'; import 'privacy_policy_page.dart'; import 'licenses_page.dart'; import 'about_page.dart';
class SettingsPage extends StatefulWidget{const SettingsPage({super.key});@override State<SettingsPage> createState()=>_SettingsPageState();}
class _SettingsPageState extends State<SettingsPage>{int reciter=7;String method='egyptian';bool busy=false;@override void initState(){super.initState();load();}Future<void> load()async{final r=await ReciterService.getSelectedReciterId();final m=await PrayerTimesService.getCalculationMethodKey();if(!mounted)return;setState((){reciter=r;method=m;});}@override Widget build(BuildContext context)=>AnimatedBuilder(animation:ThemeService.instance,builder:(c,_)=>ListView(padding:const EdgeInsets.all(16),children:[Card(child:SwitchListTile(secondary:const Icon(Icons.dark_mode),title:const Text('الوضع الليلي'),value:ThemeService.instance.isDark,onChanged:(v)=>ThemeService.instance.toggleTheme(v))),Card(child:Padding(padding:const EdgeInsets.all(16),child:DropdownButtonFormField<int>(value:reciter,decoration:const InputDecoration(labelText:'القارئ',border:OutlineInputBorder()),items:ReciterService.reciters.map((r)=>DropdownMenuItem(value:r.id,child:Text('${r.name} - ${r.style}'))).toList(),onChanged:(v)async{if(v==null)return;await ReciterService.setSelectedReciterId(v);setState(()=>reciter=v);}))),Card(child:Padding(padding:const EdgeInsets.all(16),child:DropdownButtonFormField<String>(value:method,decoration:const InputDecoration(labelText:'طريقة حساب مواقيت الصلاة',border:OutlineInputBorder()),items:PrayerTimesService.calculationMethods.entries.map((e)=>DropdownMenuItem(value:e.key,child:Text(e.value))).toList(),onChanged:(v)async{if(v==null)return;await PrayerTimesService.setCalculationMethodKey(v);setState(()=>method=v);}))),Card(child:ListTile(leading:const Icon(Icons.notifications_active),title:const Text('إعادة ضبط الإشعارات'),trailing:busy?const CircularProgressIndicator():const Icon(Icons.refresh),onTap:busy?null:()async{setState(()=>busy=true);await NotificationService.scheduleAzkarNotificationsByPrayerTimes();if(mounted)setState(()=>busy=false);})),_link(context,Icons.privacy_tip,'سياسة الخصوصية',const PrivacyPolicyPage()),_link(context,Icons.gavel,'المصادر والتراخيص',const LicensesPage()),_link(context,Icons.info_outline,'حول التطبيق',const AboutPage())]));Widget _link(BuildContext c,IconData i,String t,Widget p)=>Card(child:ListTile(leading:Icon(i),title:Text(t),trailing:const Icon(Icons.arrow_forward_ios),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>p))));}
